import{c as s,S as t,j as a,m as r}from"./chunks/framework.C68YPdek.js";const g=JSON.parse('{"title":"A run in the workspace, and a submission","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture/run-and-submission.md","filePath":"developer/architecture/run-and-submission.md"}'),o={name:"developer/architecture/run-and-submission.md"};function n(i,e,d,h,u,l){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="a-run-in-the-workspace-and-a-submission" tabindex="-1">A run in the workspace, and a submission <a class="header-anchor" href="#a-run-in-the-workspace-and-a-submission" aria-label="Permalink to “A run in the workspace, and a submission”">​</a></h1><p>Two paths cross most of the parts. Both were traced through the code on 28 November 2026.</p><h2 id="a-run-in-the-workspace" tabindex="-1">A run in the workspace <a class="header-anchor" href="#a-run-in-the-workspace" aria-label="Permalink to “A run in the workspace”">​</a></h2><ol><li>The learner picks a <strong>language</strong> (and, for some languages, an evaluator). The frontend offers the choices that the <a href="./directories">language directory</a> lists.</li><li>On Run, the frontend creates a <a href="./conductor">Conductor</a> host: it starts the evaluator&#39;s entry file, named in the directory, as a <strong>Web Worker</strong>, and registers a host plugin (<code>src/features/conductor</code>).</li><li>The frontend sends the program. The evaluator may ask the host for other files (<code>requestFile</code>); the frontend answers from the workspace&#39;s files, and serves the editor&#39;s per-run settings (the breakpoint lines) as a virtual file.</li><li>If the program imports a <strong>module</strong>, the module loader plugin finds it through the modules directory and loads the bundle.</li><li>The evaluator sends <strong>output</strong> on the <code>__stdio</code> channel, the <strong>result</strong> on <code>__result</code> and <strong>errors</strong> on <code>__error</code>; the REPL shows them. Status changes go on <code>__status</code>.</li><li>If the evaluator belongs to a <strong>tool</strong> (it names a plugin in the language directory), it asks the host to load the plugin (<code>hostLoadPlugin(id)</code>). The host looks the id up in the <a href="./directories">plugin directory</a>, imports the bundle from the URL given there, and the plugin registers its <strong>tab</strong>. The evaluator then streams its steps on the plugin&#39;s channel; the tab draws them, and can ask for a replay if it was opened late.</li></ol><h2 id="a-submission" tabindex="-1">A submission <a class="header-anchor" href="#a-submission" aria-label="Permalink to “A submission”">​</a></h2><ol><li>A student works on an assessment in the <strong>assessment workspace</strong>. Answers are saved through the backend&#39;s API (<code>answer_controller</code>), and programs can be run as above.</li><li>On <strong>submit</strong>, the backend finalises the submission (<code>Cadet.Assessments.finalise_submission</code>): it sets the status, queues a notification for the staff member, and begins <strong>autograding</strong> (<code>GradingJob.force_grade_individual_submission</code>).</li><li>For each programming question with test cases, an <strong>Oban job</strong> is queued on the <code>autograder</code> queue. The <code>LambdaWorker</code> invokes the <a href="./grader">grader</a> (an AWS Lambda function) with an event that names the evaluator, the programs and the test cases.</li><li>The grader runs each test case in the named evaluator, under a Conductor host, and returns a <code>Summary</code> of passes, failures and errors with scores.</li><li>A <code>ResultStoreWorker</code> on the <code>autograder_results</code> queue writes the result to the database.</li><li><strong>Staff</strong> grade the rest in the frontend&#39;s grading screens (the backend marks an assessment as manually graded or not, in its configuration), and the student sees the result.</li></ol><p>If the assessment&#39;s due date passes without a submission, a daily job (00:01) closes and grades the assessments that were due the day before.</p>',7)])])}const m=s(o,[["render",n]]);export{g as __pageData,m as default};
